from collections import deque
a=grid; R=C=10; seen=set(); comps=[]
for r in range(1,R):
 for c in range(C):
  if a[r][c] and (r,c) not in seen:
   col=a[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    y,x=q.pop(); comp.append((y,x))
    for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     yy,xx=p
     if 1<=yy<R and 0<=xx<C and p not in seen and a[yy][xx]==col: seen.add(p);q.append(p)
   comps.append((col,comp))
[(v, p) for v,p in comps]

# simulate components moving upward one cell per iteration if no other component or barrier
occ={p:i for i,(col,ps) in enumerate(comps) for p in ps}; positions=[set(ps) for col,ps in comps]
changed=True
while changed:
 changed=False
 for i in range(len(positions)):
  ps=positions[i]
  if all(r>1 and (r-1,c) not in occ for r,c in ps):
   for p in ps: occ.pop(p)
   ps2={(r-1,c) for r,c in ps}; positions[i]=ps2
   for p in ps2: occ[p]=i
   changed=True
